boolean isPalindrome (String s) {
    return checkRange (s, 0, s.length () - 1);
}

private boolean checkRange (String s, int lo, int hi) {
    if (lo >= hi) {
        return true;
    }
    if (s.charAt (lo) != s.charAt (hi)) {
        return false;
    }
    return checkRange (s, lo + 1, hi - 1);
}

